{
  "schema_version": "1.0",
  "summary": {
    "total_registers": 8,
    "control_state_count": 4,
    "data_pipeline_count": 4,
    "tmr_recommended_count": 4
  },
  "registers": [
    {
      "signal_name": "ctrl_state",
      "bit_width": 4,
      "category": "control_state",
      "tmr_recommended": true,
      "justification": "A single bit-flip in ctrl_state can silently redirect the FSM into an invalid or unintended control-flow state, bypassing checks with no self-correcting mechanism; TMR is required to catch this silent state corruption."
    },
    {
      "signal_name": "mode_reg",
      "bit_width": 2,
      "category": "control_state",
      "tmr_recommended": true,
      "justification": "mode_reg holds a persistent configuration/mode value; an SEU here silently changes operating mode with no downstream check, leading to unnoticed misbehavior, so TMR is warranted."
    },
    {
      "signal_name": "irq_pending_reg",
      "bit_width": 1,
      "category": "control_state",
      "tmr_recommended": true,
      "justification": "A bit-flip in irq_pending_reg can silently clear or set an interrupt-pending flag, causing a missed or spuriously triggered interrupt with no error indication, warranting TMR protection."
    },
    {
      "signal_name": "fifo_wr_ptr",
      "bit_width": 4,
      "category": "data_pipeline",
      "tmr_recommended": false,
      "justification": "fifo_wr_ptr is a pipeline addressing register whose value is refreshed each write cycle, so errors are bounded and transient, not warranting TMR."
    },
    {
      "signal_name": "fifo_rd_ptr",
      "bit_width": 4,
      "category": "control_state",
      "tmr_recommended": true,
      "justification": "fifo_rd_ptr is an address pointer; a flipped bit silently corrupts the read address, causing incorrect data retrieval from the FIFO with no self-correcting mechanism, so TMR is required."
    },
    {
      "signal_name": "mac_acc_reg",
      "bit_width": 16,
      "category": "data_pipeline",
      "tmr_recommended": false,
      "justification": "mac_acc_reg errors are bounded arithmetic deviations that are typically overwritten or accumulated over subsequent cycles, making them transient and low-priority for TMR under a fixed hardening budget."
    },
    {
      "signal_name": "data_stage1_reg",
      "bit_width": 8,
      "category": "data_pipeline",
      "tmr_recommended": false,
      "justification": "data_stage1_reg holds a transient pipeline value that is overwritten each cycle, so an SEU here produces a bounded, short-lived error not worth the area/power cost of TMR."
    },
    {
      "signal_name": "data_stage2_reg",
      "bit_width": 8,
      "category": "data_pipeline",
      "tmr_recommended": false,
      "justification": "data_stage2_reg is a transient datapath stage overwritten every cycle; its errors are bounded and typically caught by downstream checks, so TMR is not justified."
    }
  ]
}

